namespace DevinXLaserAgent;\n\ninternal static class Program\n{\n    public static async Task Main()\n    {\n        Console.Title = "DevinX Laser Agent";\n        Console.WriteLine("DevinX Laser Agent — V0 local diagnostics");\n        Console.WriteLine("This build cannot start, stop, pause, frame, control Windows, or execute remote commands.");\n        Console.WriteLine();\n\n        var lightBurn = new LightBurnUdpClient();\n\n        var ping = await lightBurn.PingAsync();\n        Console.WriteLine("LightBurn: " + ((ping.Received && ping.Response == "OK") ? "ONLINE" : "OFFLINE") + " (" + ping.Response + ")");\n\n        if (ping.Received)\n        {\n            var status = await lightBurn.StatusAsync();\n            var label = status.Response switch\n            {\n                "OK" => "CONNECTED / IDLE",\n                "!" => "BUSY OR UNAVAILABLE",\n                "?" => "INVALID RESPONSE",\n                _ => status.Response\n            };\n            Console.WriteLine("Laser status: " + label);\n        }\n\n        Console.WriteLine();\n        Console.WriteLine("Press Enter to close.");\n        Console.ReadLine();\n    }\n}\n